stages.reference_program:
PRICES = {"A1": 65, "A2": 50, "B1": 100}
COINS = ("5", "10", "25")


def change_for(amount):
    coins = []
    for coin in (25, 10, 5):
        while amount >= coin:
            coins.append(str(coin))
            amount -= coin
    return coins


credit = 0
stock = {item: 2 for item in PRICES}
message = "ready"
while True:
    print("credit", credit)
    print(message)
    parts = input().split()
    message = "ready"
    if len(parts) == 2 and parts[0] == "coin" and parts[1] in COINS:
        credit += int(parts[1])
    elif len(parts) == 2 and parts[0] == "select":
        item = parts[1]
        if item not in PRICES:
            message = "unknown " + item
        elif stock[item] == 0:
            message = "sold out " + item
        elif credit < PRICES[item]:
            message = "need " + str(PRICES[item])
        else:
            credit -= PRICES[item]
            stock[item] -= 1
            message = "vend " + item
    elif parts == ["refund"]:
        coins = change_for(credit)
        message = "change " + (" ".join(coins) if coins else "none")
        credit = 0

